'use strict';
const CONFIG = {
 measures:{title:'CPI Measures',cn:'官方整体、核心CPI同比与68类消费价格的加权通胀分布。',definition:'YoY = (Pₜ / Pₜ₋₁₂ − 1) × 100。阴影分别为P10–P25、P25–P75、P75–P90；中位数为加权P50。Headline和Core使用官方指数，缺少同比基期时保留NA。',unit:'%',cols:['month','headline','core','p10','p25','p50','p75','p90']},
 acceleration:{title:'Acceleration',cn:'同比通胀相对于12个月前的变化，观察价格涨幅的加速与减速。',definition:'Acceleration = YoYₜ − YoYₜ₋₁₂，单位为百分点。五个分位数使用当月归一化权重及累计权重线性插值。',unit:'pp',cols:['month','p10','p25','p50','p75','p90']},
 declines:{title:'Diffusion Declines',cn:'同比价格下降的消费类别占比及其消费权重占比。',definition:'严格按YoY < 0归类。类别占比 = 下跌类别数 / 68 × 100；权重占比 = 对应类别当月权重之和。仅计算单月值。',unit:'%',cols:['month','count','items_pct','weight_pct']},
 growth:{title:'Diffusion Growth',cn:'同比价格上涨的消费类别占比及其消费权重占比。',definition:'严格按YoY > 0归类。零通胀单独保留，不计入上涨或下跌。分母固定为68，使用类别自身对应权重。',unit:'%',cols:['month','count','items_pct','weight_pct']},
 t_declines:{title:'t-Diffusion Declines',cn:'同比通胀低于自身60个月历史均值超过两个样本标准差的类别。',definition:'Z = (YoYₜ − mean₆₀) / std₆₀，样本标准差ddof = 1，窗口包含当月的完整60个日历月。Z < −2归为异常偏低。',unit:'%',cols:['month','count','items_pct','weight_pct']},
 t_growth:{title:'t-Diffusion Growth',cn:'同比通胀高于自身60个月历史均值超过两个样本标准差的类别。',definition:'使用相同60个月窗口，严格按Z > 2归为异常偏高。类别占比以68为分母；权重占比使用异常类别自身当月权重。',unit:'%',cols:['month','count','items_pct','weight_pct']}
};
const LABEL={month:'Month',headline:'Headline',core:'Core',p10:'P10',p25:'P25',p50:'Median',p75:'P75',p90:'P90',count:'类别数',items_pct:'类别占比 %',weight_pct:'权重占比 %',data_status:'数据状态',valid_categories:'有效类别数',price_index:'价格指数',original_weight:'原始权重 %',weight_scale:'权重口径',normalized_weight:'归一化权重 %',yoy:'YoY %',acceleration:'Acceleration pp',mean_60:'60月均值 %',std_60:'样本标准差 pp',z_score:'Z-score',code:'BLS代码',name:'类别名称',series_id:'Series ID',decline:'YoY < 0',growth:'YoY > 0',t_decline:'Z < −2',t_growth:'Z > 2',price_status:'价格状态',weight_status:'权重状态',window_count:'有效窗口月数',window_start:'窗口起始月',yoy_uses_estimate:'同比含估算价格',acceleration_uses_estimate:'加速含估算价格',window_uses_estimate:'历史窗口含估算价格'};
const STATUS={official:'官方',estimated:'估算',provisional:'暂定',missing:'NA',complete:'完整',incomplete:'不足'};
let DATA,BASE, selectedMonthRows=[];
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(v,d=2)=>v==null||!Number.isFinite(Number(v))?'NA':Number(v).toFixed(d);
const badge=s=>`<span class="badge ${esc(s)}">${esc(STATUS[s]||s)}</span>`;
function cell(v,key){if(v==null)return 'NA';if(key.includes('status'))return badge(v);if(typeof v==='boolean')return v?'是':'否';if(typeof v==='number')return fmt(v, ['count','window_count','valid_categories'].includes(key)?0:3);if(key==='weight_scale')return v==='all_cpi_pct'?'占整体CPI %':v==='normalized_68_pct'?'68类归一化 %':esc(v);return esc(v);}
function table(el,rows,cols){el.innerHTML=`<thead><tr>${cols.map(c=>`<th scope="col">${esc(LABEL[c]||c)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${cols.map(c=>`<td>${cell(r[c],c)}</td>`).join('')}</tr>`).join('')}</tbody>`;}
function traces(key,rows){const x=rows.map(r=>r.month+'-01'), value=k=>rows.map(r=>r[k]);
 const line=(k,name,color,width=2)=>({x,y:value(k),name,type:'scatter',mode:'lines',connectgaps:false,line:{color,width},hovertemplate:`%{x|%Y-%m}<br>${name}: %{y:.3f} ${CONFIG[key].unit}<extra></extra>`});
 if(['measures','acceleration'].includes(key))return [
 {...line('p10','P10','#b9d1df',0),showlegend:false},
 {...line('p25','P10–P25','#bdd5e4',0),fill:'tonexty',fillcolor:'rgba(168,201,220,.37)',hovertemplate:'%{x|%Y-%m}<br>P25: %{y:.3f}<extra></extra>'},
 {...line('p75','P25–P75','#719db9',0),fill:'tonexty',fillcolor:'rgba(93,147,180,.42)',hovertemplate:'%{x|%Y-%m}<br>P75: %{y:.3f}<extra></extra>'},
 {...line('p90','P75–P90','#bdd5e4',0),fill:'tonexty',fillcolor:'rgba(168,201,220,.37)',hovertemplate:'%{x|%Y-%m}<br>P90: %{y:.3f}<extra></extra>'},
 line('p50','Median','#173d55',2.5),...(key==='measures'?[line('headline','Headline','#b58b40',2),line('core','Core','#9b625b',2)]:[])];
 return [line('items_pct','类别占比','#173d55',2.4),line('weight_pct','权重占比','#b58b40',2.4)];
}
function chart(key,rows){const el=$(`#chart-${key}`);return Plotly.newPlot(el,traces(key,rows),{autosize:true,width:el.clientWidth,height:el.clientHeight,margin:{l:48,r:16,t:10,b:44},paper_bgcolor:'#fff',plot_bgcolor:'#fff',font:{family:'Arial, Microsoft YaHei, sans-serif',color:'#657681',size:10},hovermode:'x unified',hoverlabel:{bgcolor:'#fff',font:{size:11}},xaxis:{type:'date',showgrid:false,tickformat:'%Y',linecolor:'#dbe3e7',rangeslider:{visible:false}},yaxis:{ticksuffix:CONFIG[key].unit==='%'?'%':'',title:{text:CONFIG[key].unit==='pp'?'Percentage points':'Percent',font:{size:10}},gridcolor:'#e9eef1',zerolinecolor:'#b8c7d0',...(key.includes('growth')||key.includes('declines')?{range:[0,100]}:{})},legend:{orientation:'h',y:-.15,x:0,font:{size:10}},showlegend:true},{responsive:true,displayModeBar:false});}
window.addEventListener('resize',()=>document.querySelectorAll('.js-plotly-plot').forEach(el=>Plotly.relayout(el,{width:el.clientWidth,height:el.clientHeight})));
function localTime(t){return t?new Date(t).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}):'尚无成功检查';}
async function load(){
 const manifest=await fetch('current.json',{cache:'no-store'}).then(r=>{if(!r.ok)throw Error('数据清单读取失败');return r.json();});
 BASE=`data/${manifest.version}/`;DATA=await fetch(manifest.path).then(r=>r.json());
 const m=DATA.meta;let status=m.status;try{const r=await fetch('status.json',{cache:'no-store'});if(r.ok)status=await r.json();}catch{}
 const calc=Object.entries(m.latest_calculation_months).map(([k,v])=>`${CONFIG[k].title}: ${v||'NA'}`).join('；');
 const allmonths=[...new Set(Object.values(m.latest_calculation_months))];
 const fields=[['最新价格月份',m.latest_price_month],['最新官方权重月份',m.latest_official_weight_month],['六组指标最新月份',allmonths.length===1?allmonths[0]:'分别查看',calc],['最后成功更新 · 北京时间',localTime(status.last_success)],['下次BLS预计发布',m.next_release?localTime(m.next_release.release_at):'等待官方日历'],['数据更新状态',({success:'检查成功',degraded:'部分来源受限',failed:'更新失败 · 保留上次数据',historical_build:'历史数据已构建'})[status.state]||status.state]];
 $('#status-grid').innerHTML=fields.map(([l,v,h])=>`<div class="status-cell"><small>${esc(l)}</small><strong title="${esc(h||v)}">${esc(v)}</strong>${h?`<small class="month-detail">${esc(h)}</small>`:''}</div>`).join('');
 $('#update-message').textContent=(status.message||'')+` · 数据构建 ${localTime(m.generated_at)} · 官方日历核验 ${localTime(m.calendar_verified_at)}`;
 $('#all-download').href=BASE+'cpi_history.xlsx';$('#provenance').href=BASE+'provenance.json';$('#quality').href=BASE+'quality.json';$('#component-download').href=BASE+'components.csv';$('#version').textContent='Data release '+m.version.slice(0,8);
 let n=0;for(const [key,c] of Object.entries(CONFIG)){n++;const rows=DATA.groups[key],last=rows.at(-1),lastGood=rows.filter(r=>r.calculation_status==='complete').at(-1);const cards=key==='measures'?['headline','core','p50']:key==='acceleration'?['p50']:['items_pct','weight_pct'];
 const box=document.createElement('section');box.id=key;box.className='indicator';box.innerHTML=`<div class="indicator-heading"><div class="indicator-title"><span class="section-number">${String(n).padStart(2,'0')}</span><div><h3>${c.title}</h3><p class="subtitle">${c.cn}</p></div></div><div class="latest">${cards.map(k=>`<div class="latest-item"><span>${LABEL[k]}</span><strong>${fmt(last[k])}${last[k]==null?'':' '+c.unit}</strong><small>${last.month}</small></div>`).join('')}</div></div><div class="chart" id="chart-${key}" role="img" aria-label="${c.title}历史交互图表"></div><div class="chart-toolbar"><div class="range-buttons" aria-label="历史范围"><button data-years="3">3Y</button><button data-years="5">5Y</button><button class="active" data-years="0">All history</button></div><div class="downloads"><span>${last.month} ${badge(last.data_status)}</span><a href="${BASE+key}.csv" download>CSV ↓</a><a href="${BASE}cpi_history.xlsx" download>Excel ↓</a></div></div><p class="definition">${c.definition} ${lastGood&&lastGood.month!==last.month?'最近完整计算月：'+lastGood.month+'。':''}</p><details class="data-panel" open><summary><span>Historical data · 历史数据表</span><span>${rows.length}个月 ▾</span></summary><div class="table-scroll"><table id="table-${key}" aria-label="${c.title}历史数据"></table></div></details>`;
 $('#indicators').append(box);table($(`#table-${key}`),[...rows].reverse(),[...c.cols,'data_status','valid_categories']);await chart(key,rows);
 box.querySelectorAll('[data-years]').forEach(b=>b.addEventListener('click',()=>{box.querySelectorAll('[data-years]').forEach(x=>x.classList.toggle('active',x===b));const years=Number(b.dataset.years);if(!years)Plotly.relayout(`chart-${key}`,{'xaxis.autorange':true});else{const end=rows.at(-1).month+'-01',date=new Date(end);date.setUTCFullYear(date.getUTCFullYear()-years);Plotly.relayout(`chart-${key}`,{'xaxis.range':[date.toISOString().slice(0,10),end]});}}));}
 const months=[...new Set(DATA.components.map(r=>r.month))].reverse();$('#month-select').innerHTML=months.map(m=>`<option>${m}</option>`).join('');$('#month-select').addEventListener('change',renderComponents);$('#component-search').addEventListener('input',renderComponents);$('#month-download').addEventListener('click',downloadMonth);renderComponents();
}
function renderComponents(){const month=$('#month-select').value,q=$('#component-search').value.toLowerCase();selectedMonthRows=DATA.components.filter(r=>r.month===month);const rows=selectedMonthRows.filter(r=>(r.code+' '+r.name+' '+r.series_id).toLowerCase().includes(q));const cols=['code','name','price_index','original_weight','weight_scale','normalized_weight','yoy','acceleration','mean_60','std_60','z_score','decline','growth','t_decline','t_growth','price_status','weight_status','window_count','window_start','yoy_uses_estimate','acceleration_uses_estimate','window_uses_estimate','series_id'];table($('#components'),rows,cols);$('#component-summary').textContent=`${month} · ${rows.length} / 68 类 · 归一化权重合计 ${selectedMonthRows.every(r=>r.normalized_weight!=null)?fmt(selectedMonthRows.reduce((s,r)=>s+r.normalized_weight,0),6)+'%':'NA'} · 价格估算 ${selectedMonthRows.filter(r=>r.price_status==='estimated').length} 类 · 暂定权重 ${selectedMonthRows.filter(r=>r.weight_status==='provisional').length} 类`;}
function downloadMonth(){const cols=Object.keys(selectedMonthRows[0]);const quote=v=>`"${String(v??'NA').replace(/"/g,'""')}"`;const csv='\uFEFF'+[cols,...selectedMonthRows.map(r=>cols.map(c=>r[c]))].map(r=>r.map(quote).join(',')).join('\r\n');const a=document.createElement('a');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.href=url;a.download=`cpi_components_${$('#month-select').value}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
load().catch(e=>{$('#update-message').textContent='数据读取失败：'+e.message+'。请用HTTP服务器运行项目，检查数据文件。';console.error(e);});
